// the buildings: the game runs when you place one (the building is there either way; a good job gets you a little back)
setTimeout(()=>{if(typeof startPlace!=='function')return;const _sp=startPlace;startPlace=function(spec){if(spec&&spec.done&&!spec._cg3){const key=spec.spr==='coop'?'coop':spec.spr==='greenhouse'?'gh':/^bench_|^furnace$/.test(spec.spr)?(spec.spr==='furnace'?'furnace':spec.spr):null;
  const def=key&&CG3_RECIPES['build:'+key];if(def){spec._cg3=1;const d0=spec.done;spec.done=function(x,z){d0.call(this,x,z);setTimeout(()=>{S.paused=true;cg3Run(def,'Building: '+spec.name,q=>{S.paused=false;if(q>.65){const back=Math.round(5+q*10);addInv('wood',back);toast(`Well built. ${back} wood left over.`,2);}});},350);};}}return _sp.apply(this,arguments);};
  const _pl=vendors.plans.rows;vendors.plans.rows=()=>_pl().map(r=>{if(r.k!=='lamps'||r._cg3)return r;const b=r.buy;return Object.assign(r,{_cg3:1,buy(){b.apply(this,arguments);setTimeout(()=>{$('shop').hidden=true;cg3Run(CG3_RECIPES['build:lamps'],'Building: field lanterns',()=>{S.paused=false;});},200);}});});},0);
